/* smooth camera rig: sph/goalT/goalFov are the GOAL; the camera follows with critically damped springs (ease-in + ease-out),
   orbiting around the target on an arc instead of cutting a straight line through the scene */
let camST=.85,vTh=0,vPh=0,lastMove=0,engaged=false;const sdv={x:0,y:0,z:0,r:0,ph:0,th:0,fov:0,ox:0,oy:0},cs=new T.Spherical(118,.95,0),TWO_PI=Math.PI*2,wrapPi=a=>((a+Math.PI)%TWO_PI+TWO_PI)%TWO_PI-Math.PI;
const sd=(cur,goal,key,st,dt)=>{const om=2/Math.max(.0001,st),x=om*dt,ex=1/(1+x+.48*x*x+.235*x*x*x),ch=cur-goal,tmp=(sdv[key]+om*ch)*dt;sdv[key]=(sdv[key]-om*tmp)*ex;let out=goal+(ch+tmp)*ex;if((goal-cur>0)===(out>goal)){out=goal;sdv[key]=0}return out};
const glide=t=>{camST=t||.85;vTh=vPh=0;cs.theta=sph.theta+wrapPi(cs.theta-sph.theta)};
const fitR=(r,fov,ex)=>ex?Math.max(r,ex/(2*Math.tan(fov*.008727)*cam.aspect)):r;
const PRE={'Map View':[[0,0,0],100,.05,50,90],'Cosmic View':[[0,12,0],118,.95,50,92],'Dome Vault':[[0,32,0],34,2.3,80,0],'Airplane Altitude (Curved Horizon)':[[0,4,-30],60,1.35,100,0],'Underworld Depths':[[0,-38,0],95,1.45,65,0],'Inside Paradise':[[-19,-44,0],9,1.45,75,0],'Inside Hades':[[19,-44,0],9,1.45,75,0],'Inside Tartarus':[[0,-67.5,0],10,1.5,75,0],'Inside Heaven':[[0,52,0],11,1.4,75,0]};
$('cams').innerHTML='<button type="button" data-tour="1" class="camera-chip camera-chip-tour">▶ Guided tour</button><button type="button" data-zoom="in" class="camera-chip camera-zoom" aria-label="Zoom in" title="Zoom in">+</button><button type="button" data-zoom="out" class="camera-chip camera-zoom" aria-label="Zoom out" title="Zoom out">−</button>'+Object.keys(PRE).map(n=>`<button type="button" data-p="${n}" class="camera-chip" aria-label="Set camera to ${n}">${n}</button>`).join('');
$('cams').querySelector('[data-p="Cosmic View"]').setAttribute('aria-pressed','true');
$('cams').onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.tour){runTour();return}if(b.dataset.zoom){stopTour();sph.radius=clamp(sph.radius*(b.dataset.zoom==='in' ? 0.86 : 1.16),3,230);camST=.32;return}const p=PRE[b.dataset.p];if(!p)return;stopTour();curPreset=b.dataset.p;goalT.set(...p[0]);sph.radius=fitR(p[1],p[3],p[4]);sph.phi=p[2];sph.theta=0;goalFov=p[3];glide();$('cams').querySelectorAll('[data-p]').forEach(q=>q.setAttribute('aria-pressed',String(q===b)))};
cam.position.setFromSpherical(sph).add(goalT);
function focus(i){const a=ANCH[i];if(!a)return;goalT.set(...a[1]);sph.radius=30;sph.phi=1.4;sph.theta=0;goalFov=55;glide();$('vt').textContent=a[0];$('vb').innerHTML=a[2].map(([r,t])=>`<div><div class="verse-reference">${r}</div><p>${t}</p></div>`).join('')+(a[4]?`<p class="verse-note">${a[4]}</p>`:'');showVerse()}
const verseEl=$('verse');
